class Solution:
    def smallestFromLeaf(self, root: Optional[TreeNode]) -> str:
        # Sentinel string larger than any valid answer
        self.result = '{' * 1000

        def is_leaf(node):
            return node is not None and node.left is None and node.right is None

        def dfs(path, node):
            if not node:
                return
            # Build the path from root to current node
            path = path + chr(ord('a') + node.val)

            # If leaf, compare reversed path (leaf → root) with current best
            if is_leaf(node) and path[::-1] < self.result:
                self.result = path[::-1]

            # Continue DFS with the new path (no mutation across siblings)
            dfs(path, node.left)
            dfs(path, node.right)

        dfs('', root)
        return self.result

