from typing import List

class Solution:
    def findRestaurant(self, list1: List[str], list2: List[str]) -> List[str]:
        # Build index map for list2
        idx2 = {word: i for i, word in enumerate(list2)}
        # Collect common strings with their index sums
        candidates = []
        for i, word in enumerate(list1):
            if word in idx2:
                candidates.append((i + idx2[word], word))
        if not candidates:
            return []
        # Sort by sum (and word for stability)
        candidates.sort()
        min_sum = candidates[0][0]
        return [word for sum_, word in candidates if sum_ == min_sum]

